import json, sys
from pathlib import Path
m=json.loads(Path(sys.argv[1]).read_text()); rate=max(0,min(100,float(m['pass_rate']))); color='#16a34a' if rate>=95 else '#f59e0b' if rate>=80 else '#dc2626'
html=f'''<!doctype html><html><head><meta charset="utf-8"><title>Quality Dashboard</title><style>body{{font-family:Arial;background:#f6f8fa;padding:24px}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}}.card{{background:#fff;border:1px solid #ddd;border-radius:12px;padding:20px}}.gauge{{height:100px;overflow:hidden}}.dial{{width:180px;height:180px;border-radius:50%;background:conic-gradient(from 270deg,{color} 0 {rate/2}%,#ddd {rate/2}% 50%,transparent 50%);margin:auto}}.value{{font-size:32px;text-align:center;margin-top:-55px;font-weight:bold}}</style></head><body><h1>Robot Quality Dashboard</h1><div class="grid"><div class="card"><h2>Pass rate</h2><div class="gauge"><div class="dial"></div></div><div class="value">{rate:.2f}%</div></div><div class="card"><h2>Execution</h2><p>Total: {m['total']}</p><p>Passed: {m['passed']}</p><p>Failed: {m['failed']}</p><p>Skipped: {m['skipped']}</p></div><div class="card"><h2>Quality Gate</h2><p>Critical failures: {m['critical_failures']}</p></div></div></body></html>'''
Path(sys.argv[2]).write_text(html,encoding='utf-8')
